(() => {
  const $=selector=>document.querySelector(selector),core=BookmarkCore;
  const cacheKey='william-bookmark-library-v1';
  let items=[],folder='',shown=90,source='none',activeBookmark=null,previewRequest=null,opener=null,scrollPosition=0;
  const isLocal=location.hostname==='127.0.0.1';
  function message(text){$('#library-status').textContent=text;}
  function theme(name){const selected=['sage','ember','crimson','sky'].includes(name)?name:'ember';document.documentElement.dataset.theme=selected;document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.palette===selected)));try{localStorage.setItem('william-palette',selected);}catch{}}
  try{theme(localStorage.getItem('william-palette'));}catch{theme('ember');}
  document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>theme(b.dataset.palette)));
  function save(){try{if($('#remember-bookmarks').checked)localStorage.setItem(cacheKey,JSON.stringify({items,source}));else localStorage.removeItem(cacheKey);}catch{message('已载入收藏，但浏览器存储空间不足；本次仍可使用。');}}
  function load(data,mode,label){items=core.normalize(data);source=mode;folder='';shown=90;$('#source-label').textContent=label;$('#sync-time').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});$('.source-bar').classList.toggle('connected',items.length>0);populate();render();save();}
  function populate(){const counts=new Map();for(const b of items){for(let i=1;i<=b.folder.length;i++){const f=b.folder.slice(0,i).join('/');counts.set(f,(counts.get(f)||0)+1);}}$('#folder-list').replaceChildren();for(const [name,count]of counts){const button=document.createElement('button');button.className='folder-button';const label=document.createElement('span');label.textContent=`${name.split('/').length>1?'↳ ':'▱ '}${name.split('/').at(-1)}`;button.title=name;button.dataset.folder=name;const number=document.createElement('span');number.textContent=count;button.append(label,number);button.addEventListener('click',()=>{folder=name;shown=90;render();});$('#folder-list').append(button);}const domains=[...new Set(items.map(b=>b.domain))].sort();$('#domain-filter').replaceChildren(new Option('全部站点',''),...domains.map(domain=>new Option(domain,domain)));$('#total-count').textContent=items.length;$('#all-count').textContent=items.length;}
  function filtered(){return core.select(items,{query:$('#bookmark-search').value,folder,domain:$('#domain-filter').value,sort:$('#sort-filter').value,duplicates:$('#duplicate-filter').checked});}
  function card(b){const el=document.createElement('article');el.className='bookmark-card';const top=document.createElement('div');top.className='bookmark-top';const icon=document.createElement('span');icon.className='bookmark-icon';icon.setAttribute('aria-hidden','true');icon.textContent=b.domain.replace(/^www\./,'')[0].toUpperCase();const domain=document.createElement('span');domain.className='bookmark-domain';domain.textContent=b.domain;top.append(icon,domain);const title=document.createElement('h3');title.className='bookmark-title';title.textContent=b.title;title.title=b.title;const crumb=document.createElement('p');crumb.className='bookmark-folder';crumb.textContent=b.folder.join(' / ')||'未分类';const actions=document.createElement('div');actions.className='bookmark-actions';const open=document.createElement('a');open.href=b.url;open.target='_blank';open.rel='noopener noreferrer';open.textContent='打开网页 ↗';open.setAttribute('aria-label',`打开网页：${b.title}`);const preview=document.createElement('button');preview.textContent='预览';preview.setAttribute('aria-haspopup','dialog');preview.setAttribute('aria-label',`预览：${b.title}`);preview.addEventListener('click',()=>openPreview(b,preview));actions.append(open,preview);el.append(top,title,crumb,actions);return el;}
  function render(){const result=filtered();$('#current-folder').textContent=folder||'全部收藏';$('#result-count').textContent=`${result.length} / ${items.length} 个入口`;$('#bookmark-results').replaceChildren(...result.slice(0,shown).map(card));$('#library-empty').hidden=result.length>0;$('#library-empty h3').textContent=items.length?'没有找到匹配的收藏。':'让收藏重新被看见。';$('#library-empty p').textContent=items.length?'换一个关键词，或重置筛选再看看。':'读取本机 Edge 收藏夹，或导入 Edge 导出的 HTML 文件。之后可以按文件夹、站点和关键词筛选。';$('#load-more').hidden=result.length<=shown;$('#load-more').textContent=`显示更多（还有 ${Math.max(0,result.length-shown)} 个）`;$('#all-folders').classList.toggle('selected',!folder);document.querySelectorAll('#folder-list button').forEach(b=>b.classList.toggle('selected',b.dataset.folder===folder));}
  async function api(url,options={}){const response=await fetch(url,{...options,headers:{'X-William-Local':'1',...(options.headers||{})},cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('本机读取工具尚未连接，请启动本机预览工具，或导入收藏文件。');}if(!response.ok)throw new Error(data.error||'读取失败');return data;}
  async function read(){if(!isLocal){message('请在本机版读取 Edge；当前页面可通过“导入文件”载入 Edge 导出的 HTML。');return;}$('#read-edge').disabled=true;message('正在读取 Edge 收藏夹…');try{const available=await api('/api/bookmarks/profiles');if(!available.profiles.length)throw new Error('没有找到 Edge 收藏夹，请先在 Edge 中收藏网页，或导入文件。');const selected=$('#edge-profile').value;$('#edge-profile').replaceChildren(...available.profiles.map(p=>new Option(p.name,p.id)));if(available.profiles.some(p=>p.id===selected))$('#edge-profile').value=selected;$('#edge-profile').hidden=available.profiles.length<=1;const data=await api('/api/bookmarks?profile='+encodeURIComponent($('#edge-profile').value));load(data.bookmarks,'edge','Edge 收藏夹 · '+$('#edge-profile').selectedOptions[0].textContent);message(`已读取 ${items.length} 个网页入口。Edge 收藏夹未被修改；新增收藏后可再次读取。`);}catch(error){message(error.message);}finally{$('#read-edge').disabled=false;}}
  $('#read-edge').addEventListener('click',read);$('#edge-profile').addEventListener('change',read);
  $('#import-bookmarks').addEventListener('click',()=>$('#bookmark-file').click());
  $('#bookmark-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw new Error('文件超过 10 MB，请导入较小的收藏文件。');const text=await file.text();let data;if(/^\s*[\[{]/.test(text)){const json=JSON.parse(text);data=json.roots?core.fromEdge(json):core.normalize(Array.isArray(json)?json:json.bookmarks||json.items);}else data=core.fromHtml(text);if(!data.length)throw new Error('没有找到 HTTP 或 HTTPS 网页，请确认导入的是收藏夹文件。');load(data,'import','已导入 · '+file.name);message(`已导入 ${items.length} 个入口，仅在本页处理。文件内容没有上传。`);}catch(error){message(error.message||'文件格式无法识别，请导入 Edge 导出的 HTML。');}e.target.value='';});
  $('#clear-bookmarks').addEventListener('click',()=>{previewRequest?.abort();if($('#bookmark-preview').open)$('#bookmark-preview').close();$('#remember-bookmarks').checked=false;load([],'none','还没有载入收藏');$('#sync-time').textContent='';reset();message('已清空本页及浏览器保存的副本。Edge 原收藏夹未改动。');});
  $('#remember-bookmarks').addEventListener('change',save);
  function reset(){folder='';$('#bookmark-search').value='';$('#domain-filter').value='';$('#sort-filter').value='source';$('#duplicate-filter').checked=false;shown=90;render();}
  $('#reset-filters').addEventListener('click',reset);$('#all-folders').addEventListener('click',()=>{folder='';shown=90;render();});
  for(const id of ['bookmark-search','domain-filter','sort-filter','duplicate-filter'])$('#'+id).addEventListener(id==='bookmark-search'?'input':'change',()=>{shown=90;render();});
  $('#load-more').addEventListener('click',()=>{shown+=90;render();});
  for(const view of ['grid','list'])$('#'+view+'-view').addEventListener('click',()=>{$('#bookmark-results').classList.toggle('list-view',view==='list');for(const other of ['grid','list'])$('#'+other+'-view').setAttribute('aria-pressed',String(other===view));});
  async function openPreview(b,button){previewRequest?.abort();activeBookmark=b;opener=button;scrollPosition=scrollY;$('#preview-title').textContent=b.title;$('#preview-domain').textContent=b.domain;$('#preview-folder').textContent=b.folder.join(' / ');$('#preview-open').href=b.url;$('#preview-url').textContent=b.url;$('#preview-frame').removeAttribute('src');$('#preview-frame-wrap').hidden=true;$('#preview-summary').replaceChildren();$('#bookmark-preview').showModal();$('#bookmark-preview').scrollTop=0;document.body.style.overflow='hidden';$('#close-preview').focus({preventScroll:true});if(source!=='edge'){ $('#preview-summary').textContent=b.description||'已载入收藏信息。点击“加载网页画面”查看网页，或在新标签打开。内容摘要需要本机 Edge 读取模式。';return;}$('#preview-summary').textContent='正在读取公开网页的文本摘要…';const controller=new AbortController();previewRequest=controller;const timer=setTimeout(()=>controller.abort(),20000);try{const data=await api('/api/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:b.url,profile:$('#edge-profile').value}),signal:controller.signal});if(activeBookmark!==b||!$('#bookmark-preview').open)return;const heading=document.createElement('h3');heading.textContent=data.title||b.title;const desc=document.createElement('p');desc.textContent=data.description||'';const text=document.createElement('p');text.textContent=data.text||'此网页没有可提取的正文，可能需要登录或依赖脚本加载。';const note=document.createElement('small');note.textContent='网页文本摘要 · 不包含 Edge 登录信息，排版与原网页不同。';$('#preview-summary').replaceChildren(heading,desc,text,note);}catch(error){if(activeBookmark===b&&$('#bookmark-preview').open)$('#preview-summary').textContent=error.name==='AbortError'?'读取超时，请加载网页画面或打开原网页。':error.message;}finally{clearTimeout(timer);}}
  $('#embed-preview').addEventListener('click',()=>{if(!activeBookmark)return;$('#preview-frame-wrap').hidden=false;$('#preview-frame').src=activeBookmark.url;});
  $('#close-preview').addEventListener('click',()=>$('#bookmark-preview').close());
  $('#bookmark-preview').addEventListener('close',()=>{previewRequest?.abort();activeBookmark=null;$('#preview-frame').removeAttribute('src');document.body.style.overflow='';window.scrollTo({top:scrollPosition,behavior:'instant'});opener?.focus({preventScroll:true});});
  $('#bookmark-preview').addEventListener('click',e=>{const box=$('#bookmark-preview').getBoundingClientRect();if(e.target===$('#bookmark-preview')&&(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom))$('#bookmark-preview').close();});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#bookmark-preview').open&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#bookmark-search').focus();}});
  try{const cached=JSON.parse(localStorage.getItem(cacheKey)||'null');if(cached?.items){$('#remember-bookmarks').checked=true;load(cached.items,'import','此浏览器保存的收藏');}}catch{message('本地缓存无法读取，请重新载入收藏。');}
  render();if(isLocal)read();else message('点击“导入文件”即可开始。在线页面不会读取或上传本机 Edge 数据。');
})();
